/** Expo config plugin: gives the Android Gradle build enough JVM memory (docs/release.md).
 *
 *  `android/` is gitignored and regenerated by `expo prebuild`, whose template ships
 *  `org.gradle.jvmargs=-Xmx2048m -XX:MaxMetaspaceSize=512m`. With Expo SDK 57's module set that is
 *  too little: `:expo-updates:kspReleaseKotlin` fails with `OutOfMemoryError: Metaspace` and the
 *  daemon hangs. This plugin replaces the key in the generated `android/gradle.properties` (never
 *  adds a second one), for local builds, the CI release job and EAS alike. GitHub's Ubuntu runners
 *  have 16 GB, so a 4 GB heap fits. */
const { withGradleProperties } = require('expo/config-plugins');

const JVM_ARGS_KEY = 'org.gradle.jvmargs';
const JVM_ARGS =
  '-Xmx4096m -XX:MaxMetaspaceSize=1536m -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8';

/** Sets `org.gradle.jvmargs` in a parsed gradle.properties list (the shape Expo's
 *  `withGradleProperties` hands over): the first entry is updated in place, any duplicates are
 *  dropped, and the key is appended when the template has none. */
function applyGradleMemory(properties) {
  let seen = false;
  const out = [];
  for (const item of properties) {
    if (item.type === 'property' && item.key === JVM_ARGS_KEY) {
      if (seen) continue;
      seen = true;
      out.push({ ...item, value: JVM_ARGS });
    } else {
      out.push(item);
    }
  }
  if (!seen) out.push({ type: 'property', key: JVM_ARGS_KEY, value: JVM_ARGS });
  return out;
}

function withGradleMemory(config) {
  return withGradleProperties(config, (c) => {
    c.modResults = applyGradleMemory(c.modResults);
    return c;
  });
}

module.exports = withGradleMemory;
module.exports.applyGradleMemory = applyGradleMemory;
module.exports.JVM_ARGS = JVM_ARGS;
